local GachaponNumberOfRoundsCell = Class('GachaponNumberOfRoundsCell')
local UISwitchImage = typeof(CS.Game.Native.Common.UISwitchImage)
local UIModule = CS.Engine.UI.UIModule
local GameObjects = {
    Normal = { path = "Normal" },
    Choose = { path = "Choose" },
}
local Components = {
    Normal_ImgShadow = { path = "Normal/ImgShadow"  , comp = UISwitchImage },
    Normal_ImgBtn = { path = "Normal/ImgBtn",comp = UISwitchImage},
    Choose_ImgShadow = { path = "Choose/ImgShadow"  , comp = UISwitchImage },
    Choose_ImgBtn = { path = "Choose/ImgBtn",comp = UISwitchImage},
    Choose_ImgArrow = { path = "Choose/ImgArrow",comp = UISwitchImage},
}
local Animations = {
    Normal = "View_Cell_Normal",
    Choose_SSR = "View_Cell_Choose_SSR",
    Choose_noSSR = "View_Cell_Choose_noSSR",
}

function GachaponNumberOfRoundsCell:__init()
    
    self.isSelect = false
    self.cardDatas = nil
    self.isHaveSSR = nil
    self.selectIndex = nil
    self.dialogId = nil
end

function GachaponNumberOfRoundsCell:__delete()
    
    self.cardDatas = nil
    self.isHaveSSR = nil
    self.dialogId = nil
end

function GachaponNumberOfRoundsCell:Awake()
    ---@type UnityEngine.Transform
    local transform = self.controller.gameObject.transform
    ---@type UnityEngine.UI.Toggle
    for key, v in pairs(Components) do
        self[key] = self:GetComponent(transform , v)
    end

    for key, v in pairs(GameObjects) do
        self[key] = self:GetGameObject(transform ,v)
    end
    local toggle = self.controller.gameObject.transform:GetComponent(typeof(CS.UnityEngine.UI.Toggle))
    self.Toggle = toggle
    self.Animation = self.controller.gameObject.transform:GetComponent(typeof(CS.UnityEngine.Animation))
    SetToggleValueChanged(toggle,Bind(self, self.OnClick))
end
function GachaponNumberOfRoundsCell:SetData(data , index , id )
    self.cardDatas = data
    self.isHaveSSR = self:IsHaveSSR()
    self.selectIndex = index
    self.dialogId = id
end

function GachaponNumberOfRoundsCell:InitUI()
    local index = self.isHaveSSR  and 1 or 2
    self.Normal_ImgBtn.Status = index
    self.Normal_ImgShadow.Status = index
    self.Choose_ImgBtn.Status = index
    self.Choose_ImgArrow.Status = index
    self.Choose_ImgShadow = index
end
--- 设置Toggle 是否是选中状态
---@param value boolean 是指Toggle 是否是选中状态
function GachaponNumberOfRoundsCell:SetToggleSelect(value)
    self.Toggle.isOn = value

end
--- 判断是否存在SSR
---@return  boolean
function GachaponNumberOfRoundsCell:IsHaveSSR()
    local isHaveSSR = false
    local SSR = Constants.RareType.SSR
    local CardConfMgr =  CardConfMgr:GetInstance()
    for index , cardData in pairs(self.cardDatas) do
        local eachResultCardVo  = CardConfMgr:GetCardByRefId(cardData.goodsId)
        if eachResultCardVo.rare == SSR then
            isHaveSSR = true
            break
        end
    end
    return isHaveSSR
end

function GachaponNumberOfRoundsCell:RefreshUI()
    self:PlayAnimation()
end

--- 播放对应的动画
function GachaponNumberOfRoundsCell:PlayAnimation()
    if not self.Toggle.isOn then
        self.Animation:Play(Animations.Normal)
        return
    end
    if self.isHaveSSR then
        self.Animation:Play(Animations.Choose_SSR)
        return
    else
        self.Animation:Play(Animations.Choose_noSSR)
        return
    end
    self.Animation:Play(Animations.Normal)
end


function GachaponNumberOfRoundsCell:OnClick(value)
    self:SetToggleSelect(value)
    self:RefreshUI()
    if value then
        ---@type Engine.UI.UILuaDialog
        local dialog = UIModule.CurrentScreen:GetDialog(self.dialogId)
        if (not isNull(dialog)) and dialog.Env.SetToggleSelectIndex  then
            dialog.Env:SetToggleSelectIndex(self.selectIndex)
        end
    end
end
function GachaponNumberOfRoundsCell:Start()

end

function GachaponNumberOfRoundsCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

