---@param compTable {path ='' ,  comp = ''}
function GachaponNumberOfRoundsCell:GetComponent(transform, compTable)
    ---@type UnityEngine.GameObject
    local gameObject = transform.transform:Find(compTable.path)
    if not isNull(gameObject) then
        local comp = gameObject.transform:GetComponent(compTable.comp)
        return comp
    end
end

---@param transform UnityEngine.GameObject
---@param compTable {path ='' ,  comp = ''}
---@return UnityEngine.GameObject
function GachaponNumberOfRoundsCell:GetGameObject(transform, compTable)
    ---@type UnityEngine.GameObject
    local gameObject = transform.transform:Find(compTable.path)
    return gameObject
end


